#include <iostream>
#include <vector>
#include <cstdint>

int64_t count_digits(int64_t num) {
    num = (num < 0) ? -num : num;
    int64_t count = 0;
    while (num) {
        ++count;
        num /= 10;
    }
    return count;
}

int64_t generate_ones(int64_t length) {
    int64_t result = 0;
    for (int i = 0; i < length; ++i)
        result = 10 * result + 1;
    return result;
}

int64_t recursive_aux2(int64_t num) {
    if (num == 0) return 0;
    num = (num < 0) ? -num : num;
    int64_t digits = count_digits(num);
    return digits + recursive_aux2(num - generate_ones(digits));
}

int64_t recursive_aux(int64_t num, int64_t sign, int64_t accumulated, int64_t max_value, std::vector<int>& state) {
    if (accumulated >= max_value) return max_value;
    if (num == 0) return accumulated;
    if (num < 0) { num = -num; sign = -sign; }
    int64_t d = count_digits(num);
    int64_t ones_d = generate_ones(d);
    int64_t res_option1 = max_value, res_option2 = max_value;

    if (0 <= state[d] * sign && -10 < state[d] && state[d] < 10) {
        state[d] += sign;
        res_option1 = recursive_aux(num - ones_d, sign, accumulated + d, max_value, state);
        state[d] -= sign;
    }
    if (0 <= state[d + 1] * sign && -10 < state[d + 1] && state[d + 1] < 10) {
        state[d + 1] += sign;
        res_option2 = recursive_aux(num - 10 * ones_d - 1, sign, accumulated + d + 1, res_option1, state);
        state[d + 1] -= sign;
    }
    return res_option1 < res_option2 ? res_option1 : res_option2;
}

int main() {
    int64_t n;
    std::cin >> n;
    std::vector<int> state(20, 0);
    std::cout << recursive_aux(n, 1, 0, recursive_aux2(n), state) << std::endl;
    return 0;
}
